using System;
using System.Reflection;
using System.Linq;
using System.Collections.Generic;

class ApiExplorer
{
    static void Main()
    {
        var agentsPath = "/home/runner/.nuget/packages/microsoft.agents.ai/1.9.0/lib/net8.0/Microsoft.Agents.AI.dll";
        var extensionsPath = "/home/runner/.nuget/packages/microsoft.extensions.ai/10.6.0/lib/net8.0/Microsoft.Extensions.AI.dll";

        Console.WriteLine("=== MICROSOFT.AGENTS.AI (v1.9.0) ===\n");
        ExploreAssembly(agentsPath);

        Console.WriteLine("\n\n=== MICROSOFT.EXTENSIONS.AI (v10.6.0) ===\n");
        ExploreAssembly(extensionsPath);
    }

    static void ExploreAssembly(string path)
    {
        try
        {
            var asm = Assembly.LoadFrom(path);
            var types = asm.GetExportedTypes()
                .OrderBy(t => t.Name)
                .ToList();

            Console.WriteLine($"Exported Types ({types.Count}):\n");

            // Find key types
            var keyNames = new[] { "ChatClientAgent", "AgentWorker", "Agent", "Tool", "AITool", "AIFunction", "AgentInvokeOptions", "InvokeOptions" };

            foreach (var typeName in keyNames)
            {
                var type = types.FirstOrDefault(t => t.Name.Contains(typeName, StringComparison.OrdinalIgnoreCase));
                if (type != null)
                {
                    PrintType(type);
                }
            }

            // Also print all public classes and interfaces
            Console.WriteLine("\n=== ALL PUBLIC TYPES ===\n");
            foreach (var type in types.Where(t => t.IsPublic && (t.IsClass || t.IsInterface)))
            {
                Console.WriteLine($"{(type.IsInterface ? "interface" : "class")} {type.Name}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    static void PrintType(Type type)
    {
        var modifier = type.IsInterface ? "interface" : type.IsClass ? "class" : "struct";
        Console.WriteLine($"\n[{modifier}] {type.FullName}");

        // Constructors
        var ctors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        if (ctors.Length > 0)
        {
            Console.WriteLine("  Constructors:");
            foreach (var ctor in ctors)
            {
                var parms = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"    {type.Name}({parms})");
            }
        }

        // Methods
        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly);
        if (methods.Length > 0)
        {
            Console.WriteLine("  Methods:");
            foreach (var method in methods.OrderBy(m => m.Name))
            {
                var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"    {method.ReturnType.Name} {method.Name}({parms})");
            }
        }

        // Properties
        var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static);
        if (props.Length > 0)
        {
            Console.WriteLine("  Properties:");
            foreach (var prop in props.OrderBy(p => p.Name))
            {
                Console.WriteLine($"    {prop.PropertyType.Name} {prop.Name} {{ {(prop.CanRead ? "get" : "")} {(prop.CanWrite ? "set" : "")} }}");
            }
        }
    }
}
