void ExploreAssembly(string path)
{
    try
    {
        var asm = Assembly.LoadFrom(path);
        var types = asm.GetExportedTypes().OrderBy(t => t.Name).ToList();

        Console.WriteLine($"Total Exported Types: {types.Count}\n");

        // Key types to search
        var keyNames = new[] { "ChatClientAgent", "AgentWorker", "Agent", "Tool", "AITool", "AIFunction", "AgentInvokeOptions", "InvokeOptions", "AgentState" };

        foreach (var typeName in keyNames)
