            {
                title = $"{query}: A Practical Guide",
                url = $"https://example.com/guide/{Uri.EscapeDataString(query)}",
                snippet = $"A practical guide to understanding {query}, with real-world applications, best practices, and expert insights."
            }
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to record
/// and organize findings during a research session.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Save a research note with a topic label and content. Use this to record important findings from web searches.")]
    public string SaveNote(
        [Description("A short topic label for the note (e.g., 'key finding', 'definition', 'statistic')")] string topic,
        [Description("The content of the note")] string content,
        [Description("The source URL where this information was found, if available")] string? sourceUrl = null)
    {
        var note = new Note(topic, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(note);
        _logger.LogInformation("Note saved: [{Topic}] ({Length} chars)", topic, content.Length);
        return $"Note #{_notes.Count} saved under topic '{topic}'.";
    }

    [Description("Retrieve all saved research notes. Use this before writing a summary to review what you've collected.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var output = _notes.Select((n, i) => new
        {
            id = i + 1,
            topic = n.Topic,
            content = n.Content,
            source = n.SourceUrl ?? "N/A",
            savedAt = n.SavedAt.ToString("u")
        });

        _logger.LogInformation("Retrieved {Count} notes", _notes.Count);
        return JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true });
    }

    [Description("Get notes filtered by topic label. Useful for organizing findings by category.")]
    public string GetNotesByTopic(
        [Description("The topic label to filter by (case-insensitive partial match)")] string topic)
    {
        var filtered = _notes
            .Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase))
            .Select((n, i) => new
            {
                id = i + 1,
                topic = n.Topic,
                content = n.Content,
                source = n.SourceUrl ?? "N/A"
            })
            .ToList();

        if (filtered.Count == 0)
        {
            return $"No notes found matching topic '{topic}'.";
        }

        return JsonSerializer.Serialize(filtered, new JsonSerializerOptions { WriteIndented = true });
    }

    private sealed record Note(string Topic, string Content, string? SourceUrl, DateTime SavedAt);
}

