using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability using the Brave Search API.
/// Falls back to simulated results when no API key is configured.
/// </summary>
public sealed class WebSearchTool
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly ILogger<WebSearchTool> _logger;
    private readonly string? _braveApiKey;

    public WebSearchTool(
        IHttpClientFactory httpClientFactory,
        ILogger<WebSearchTool> logger)
    {
        _httpClientFactory = httpClientFactory;
        _logger = logger;
        _braveApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
    }

    [Description("Search the web for information on a given query. Returns a list of relevant results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);
        _logger.LogInformation("Web search: \"{Query}\" (max {Max} results)", query, maxResults);

        if (!string.IsNullOrEmpty(_braveApiKey))
        {
            return await SearchWithBraveAsync(query, maxResults);
        }

        _logger.LogWarning("BRAVE_API_KEY not set — returning simulated results");
        return GetSimulatedResults(query);
    }

    private async Task<string> SearchWithBraveAsync(string query, int maxResults)
    {
        using var client = _httpClientFactory.CreateClient("BraveSearch");
        client.DefaultRequestHeaders.Add("X-Subscription-Token", _braveApiKey);
        client.DefaultRequestHeaders.Add("Accept", "application/json");

        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}";
        var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = new List<object>();

        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var webResults))
        {
            foreach (var result in webResults.EnumerateArray().Take(maxResults))
            {
                results.Add(new
                {
                    title = result.GetProperty("title").GetString(),
                    url = result.GetProperty("url").GetString(),
                    snippet = result.TryGetProperty("description", out var desc)
                        ? desc.GetString()
                        : "No description available"
                });
            }
        }

        _logger.LogInformation("Brave search returned {Count} results", results.Count);
        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }

    private static string GetSimulatedResults(string query)
    {
        var results = new[]
        {
            new
            {
                title = $"Overview of {query} - Wikipedia",
                url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                snippet = $"A comprehensive overview of {query}, covering history, key concepts, and recent developments in the field."
            },
            new
            {
                title = $"Latest Research on {query}",
                url = $"https://arxiv.org/search/?query={Uri.EscapeDataString(query)}",
                snippet = $"Recent academic papers and research findings related to {query}, including breakthroughs and ongoing studies."
            },
            new
            {
                title = $"{query}: A Practical Guide",
                url = $"https://example.com/guide/{Uri.EscapeDataString(query)}",
                snippet = $"A practical guide to understanding {query}, with real-world applications, best practices, and expert insights."
            }
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

