using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// ── Configuration ──────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ── DI container ───────────────────────────────────────────────────────────
var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

services.AddHttpClient();
services.AddSingleton<WebSearchTool>();
services.AddSingleton<NoteTakingTool>();

services.AddChatClient(builder => builder
    .UseLogging()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId)));

var provider = services.BuildServiceProvider();

var chatClient = provider.GetRequiredService<IChatClient>();
var loggerFactory = provider.GetRequiredService<ILoggerFactory>();
var logger = loggerFactory.CreateLogger("ResearchAgent");

// ── Build tools from annotated methods ─────────────────────────────────────
var webSearch = provider.GetRequiredService<WebSearchTool>();
var noteTaking = provider.GetRequiredService<NoteTakingTool>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTaking.SaveNote),
    AIFunctionFactory.Create(noteTaking.GetAllNotes),
    AIFunctionFactory.Create(noteTaking.GetNotesByTopic),
};

// ── Create the research agent ──────────────────────────────────────────────
var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
        Tools = tools,
        Instructions = """
            You are a thorough research assistant. When given a topic:

            1. Use the SearchWebAsync tool to search for information (run 2-3 searches with different queries).
            2. Use the SaveNote tool to record key findings, facts, and statistics from each search.
            3. Use GetAllNotes to review everything you've collected.
            4. Produce a well-structured summary with:
               - An introduction to the topic
               - Key findings organized by theme
               - Source attributions for each claim
               - A brief conclusion

            Always cite your sources. Be factual and objective.
            """,
    },
};

var agent = new ChatClientAgent(chatClient, agentOptions, loggerFactory);
var session = await agent.CreateSessionAsync();

// ── Interactive loop ───────────────────────────────────────────────────────
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (MAF)           ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.ResetColor();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("\n🔎 Research topic: ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine("Goodbye!");
        break;
    }

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"Researching \"{topic}\"… (the agent will search, take notes, and summarize)\n");
    Console.ResetColor();

    try
    {
        var response = await agent.RunAsync(
            $"Research the following topic and produce a comprehensive summary: {topic}",
            session);

        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine("── Research Summary ──────────────────────────────────");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine("─────────────────────────────────────────────────────");
        Console.ResetColor();
    }
    catch (Exception ex)
    {
        logger.LogError(ex, "Agent execution failed");
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

